head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[textarea > M > setValue]<br/>Textarea 컴포넌트의 실제 입력값을 설정합니다.",
    "validation" : [
        "value(필수) 파라미터로 Textarea 컴포넌트의 실제 입력값을 설정합니다.",
        "value(필수) 파라미터가 null 이면 메소드가 실행되지 않아 이전 값이 그대로 유지됩니다.",
        "value(필수) 파라미터에 줄바꿈(\\n) 이 포함된 텍스트는 그대로 반영되어 여러 줄로 설정됩니다.",
        "setValue() 메소드로 입력값이 변경된 경우 onchange 이벤트는 발생하고, onviewchange 이벤트는 발생하지 않습니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.getValue = function (target) {
    let rtn = target.getValue();
    wf_body_bottom.getObj("scwin").setReturnValue("getValue : [" + rtn + "] (type=" + typeof rtn + ", length=" + rtn.length + ")");
}



// target1 (정상 문자열 설정 — value 필수 파라미터)
scwin.btn_setValue1_onclick = function (e) {
    target1.setValue("abc123ABC");
    target1.focus();
};

scwin.btn_getValue1_onclick = function (e) {
    scwin.getValue(target1);
}


// target2 (null 파라미터 — 메서드 미실행, 이전 값 유지)
scwin.btn_setValue2_onclick = function (e) {
    target2.setValue(null);
    target2.focus();
};

scwin.btn_getValue2_onclick = function (e) {
    scwin.getValue(target2);
}


// target3 (줄바꿈 "\n" 포함 텍스트 — 여러 줄로 설정)
scwin.btn_setValue3_onclick = function (e) {
    let text = "Inswave \n"
             + "WebSquare \n"
             + "ProWorks \n";
    target3.setValue(text);
    target3.focus();
};

scwin.btn_getValue3_onclick = function (e) {
    scwin.getValue(target3);
}


// target4 (setValue 호출 시 onchange 발생, onviewchange 미발생 검증)
scwin.btn_setValue4_onclick = function (e) {
    target4.setValue("event check");
    target4.focus();
};

scwin.btn_getValue4_onclick = function (e) {
    scwin.getValue(target4);
}


scwin.btn_setAll_onclick = function (e) {
    for (var i = 1; i < 5; i ++)
        eval("scwin.btn_setValue"+i+"_onclick()");
}

scwin.btn_getAll_onclick = function (e) {
    for (var i = 1; i < 5; i ++)
        eval("scwin.btn_getValue"+i+"_onclick()");
};


scwin.target_onchange = function (info) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target_onchange=====");
};



scwin.target_onviewchange = function (info) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target_onviewchange=====");
};
